import {DynamicDrawUsage} from 'three';
// Positions/normals change without rebuilding immutable UV/index buffers.
export function geometryStreamStamp(geometry,attributeId,dynamicSupported=false){const p=geometry.attributes.position,n=geometry.attributes.normal,dynamic=!!(dynamicSupported&&p?.usage===DynamicDrawUsage&&p.itemSize===3&&n?.itemSize===3&&n.count===p.count),attributes=Object.entries(geometry.attributes).filter(([name])=>!['shotPosition','skinIndex','skinWeight'].includes(name)),base=[attributeId(geometry.index),geometry.index?.version,dynamic],stamp=a=>a.isInterleavedBufferAttribute?a.data.version:a.version;return{dynamic,layout:JSON.stringify([...base,...attributes.map(([name,a])=>[name,attributeId(a),a.count,a.itemSize,dynamic&&['position','normal'].includes(name)?null:stamp(a)])]),signature:JSON.stringify([...base,...attributes.map(([name,a])=>[name,attributeId(a),a.count,a.itemSize,stamp(a)])])};}
export function packedDynamicVertices(geometry,out=[]){const p=geometry.attributes.position,n=geometry.attributes.normal;out.length=p.count*6;for(let i=0;i<p.count;i++){const at=i*6;out[at]=p.getX(i);out[at+1]=p.getY(i);out[at+2]=p.getZ(i);out[at+3]=n.getX(i);out[at+4]=n.getY(i);out[at+5]=n.getZ(i);}if(out.some(v=>!Number.isFinite(v)))throw Error('동적 메시 위치·법선이 유한해야 해요.');return out;}
